// The music video setting: live-action shots generated by MiniMax H3, cut together with the
// engine's code shots, and a pop-video camera that plays the track.
//   node photoreal/musicvideo.mjs --song ../my-video                 everything that isn't done yet
//   node photoreal/musicvideo.mjs --song ../my-video --stage music   the beat map and hits only
//   stages: music | code | h3 | join | all (default)   options: [--skip-storyboard] [--no-popcam] [--no-tuck]
//
// film.json:
//   { "mode": "musicvideo", "fps": 24, "popcam": { "energy": 1 },
//     "photorealistic": { "style": "<the look of every generated shot>", "tuck": true, "takes": [...] },
//     "scenes": [
//       { "id": "01", "source": "h3", "from": 0, "to": 6.4,
//         "photorealistic": { "prompt": "<the shot, as live action>", "look": "looks/01.png", "proxy": "greybox/01.mp4" },
//         "camera": { "energy": 1.2 } },
//       { "id": "02", "scene": "ridge", "from": 6.4, "to": 12.8 },                       a code shot
//       { "id": "03", "source": "h3", "scene": "ark-side", "from": 12.8, "to": 20,       a code shot H3 repaints,
//         "photorealistic": { "prompt": "..." } }                                         keeping its code words
//     ] }
//
// This is the one setting that is mostly generated, by Shane's choice (2026-10-14: "a music video
// setting where we could make live action movies with H3 ... fully use generated video ... or mixed
// with rendered as most videos are"). The finished film is labelled as containing generated video
// (out/film.label.txt), and so is anything published from it. The rest of the engine stays as it was:
// the render tiers are pure code, and shake stays off outside this setting.
//
// What it does, in order:
//   music  data/music.json, the beat map, hits, swells and fills (lib/music.py), when it is missing
//   code   the code shots, through film.mjs --only (the film's tier, every safeguard of a normal render)
//   h3     the generated shots, through photorealistic.mjs (H3 on the machine with ComfyUI, one GPU job
//          at a time through its dashboard queue); a live-action shot is steered by its greybox
//          "proxy" when it has one, and by its prompt and look alone when it doesn't
//   join   every shot conformed to 1920x1080 at 24 fps on exact frame counts, the pop camera laid over
//          the cut (lib/popcam.py), the song under it: out/film.mp4
// Then, as for every film: node photoreal/check.mjs --label final and node photoreal/critic.mjs film.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { resolveTier } from './lib/tier.mjs';
import { storyboardPath } from './lib/storyboard.mjs';
import { writeStatus } from './lib/progress.mjs';
import { H3 } from './lib/h3.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));

// ---------- the film as written ----------
export function validate(f, songDir) {
  const errs = [];
  if (f.mode !== 'musicvideo') errs.push('film.json needs "mode": "musicvideo"');
  if ((f.fps ?? 60) !== H3.fps) errs.push(`a music video runs at H3's ${H3.fps} fps: set "fps": ${H3.fps} in film.json`);
  const sc = f.scenes ?? [];
  if (!sc.length) errs.push('no scenes');
  for (let i = 1; i < sc.length; i++) if (Math.abs(sc[i].from - sc[i - 1].to) > 1e-6) errs.push(`gap or overlap between ${sc[i - 1].id} and ${sc[i].id}`);
  const takes = f.photorealistic?.takes ?? [];
  for (const s of sc) {
    if (s.source !== undefined && s.source !== 'h3' && s.source !== 'code') errs.push(`scene ${s.id}: "source" is "h3" or "code"`);
    if (s.source !== 'h3' && !s.scene) errs.push(`scene ${s.id} is a code shot with no "scene" module; give it one, or "source": "h3" to generate it`);
    if (s.scene && songDir && !fs.existsSync(path.join(songDir, 'scenes', `${s.scene}.js`))) errs.push(`scene ${s.id}: no scenes/${s.scene}.js`);
    const inTake = takes.find((t) => t.scenes.includes(s.id));
    if (s.source === 'h3' && !s.photorealistic?.prompt && !inTake?.prompt) errs.push(`scene ${s.id} is generated and needs "photorealistic": { "prompt": "<the shot, as live action>" }`);
    const proxy = s.photorealistic?.proxy ?? inTake?.proxy;
    if (proxy && songDir && !fs.existsSync(path.resolve(songDir, proxy))) errs.push(`scene ${s.id}: no guide video at ${proxy}`);
    if (s.source === 'h3' && s.to - s.from > 60) errs.push(`scene ${s.id} is ${(s.to - s.from).toFixed(1)} s; a generated shot that long drifts, split it into shots of 4 to 15 s`);
  }
  return errs;
}

// the frames each scene owns on the film's 24 fps grid
export const framesOf = (s) => Math.round(s.to * H3.fps) - Math.round(s.from * H3.fps);

// where film.mjs leaves a code shot's segment (the same rule it writes by)
export function codeSegment(OUT, s, tier) {
  const st = tier === 'fast' ? 'fast' : s.tier === 'premium' ? 'premium' : tier;
  const dir = st === 'standard' ? 'segments' : `segments-${st}`;
  return path.join(OUT, dir, `${s.id}.mp4`);
}

// the generated pieces in order: a take covering several scenes is one file
export function units(f) {
  const takes = f.photorealistic?.takes;
  const h3 = f.scenes.filter((s) => s.source === 'h3');
  return takes ? takes.map((t) => ({ id: t.id, scenes: t.scenes })) : h3.map((s) => ({ id: s.id, scenes: [s.id] }));
}

if (fileURLToPath(import.meta.url) === path.resolve(process.argv[1] ?? "")) {
  const argv = process.argv.slice(2);
  const opt = (k, d) => { const i = argv.indexOf('--' + k); return i >= 0 ? argv[i + 1] : d; };
  const flag = (k) => argv.includes('--' + k);
  const SONG = path.resolve(opt('song', '.'));
  const film = JSON.parse(fs.readFileSync(path.join(SONG, 'film.json'), 'utf8'));
  const stage = opt('stage', 'all');
  const doing = (k) => stage === 'all' || stage === k;
  const OUT = path.join(SONG, 'out'), WORK = path.join(OUT, 'work', 'musicvideo');
  fs.mkdirSync(WORK, { recursive: true });
  const notes = [];
  const started = Date.now();
  const readJson = (f) => { try { return JSON.parse(fs.readFileSync(f, 'utf8')); } catch { return null; } };
  const sha = (s) => crypto.createHash('sha256').update(s).digest('hex');
  const run = (cmd, args, what) => {
    console.log(`\n== ${what}`);
    const r = spawnSync(cmd, args, { stdio: 'inherit' });
    if (r.status !== 0) blocked(`${what} failed (${cmd} exited ${r.status}).`);
  };
  const ff = (args, what) => { const r = spawnSync('ffmpeg', ['-y', '-loglevel', 'error', ...args], { stdio: 'inherit' }); if (r.status !== 0) blocked(`${what} failed.`); };
  function blocked(reason) {
    writeStatus(path.join(OUT, 'STATUS.md'), { song: SONG, state: 'blocked', notes: [reason, ...notes], elapsed: (Date.now() - started) / 1000 });
    console.error(reason);
    process.exit(2);
  }

  const errs = validate(film, SONG);
  if (errs.length) { for (const e of errs) console.error('-', e); process.exit(1); }
  const scenes = film.scenes;
  const code = scenes.filter((s) => s.source !== 'h3'), gen = scenes.filter((s) => s.source === 'h3');
  const { tier } = resolveTier(SONG, film, opt('tier'));
  console.log(`music video: ${scenes.length} shots, ${gen.length} generated and ${code.length} code (${tier} tier)`);

  // ---------- music ----------
  const musicFile = path.join(SONG, 'data', 'music.json');
  if (doing('music') && !fs.existsSync(musicFile)) run('python3', [path.join(HERE, 'lib', 'music.py'), '--song', SONG], 'the beat map, hits and swells (lib/music.py)');
  if (stage === 'music') process.exit(0);

  // ---------- the storyboard gate, as for every film ----------
  const sb = storyboardPath(SONG), sbReview = readJson(path.join(OUT, 'review', 'storyboard-review.json'));
  if (flag('skip-storyboard')) notes.push('The storyboard gate was skipped with --skip-storyboard.');
  else if (!fs.existsSync(sb)) blocked(`No storyboard. Write ${path.relative(SONG, sb)} (node photoreal/storyboard.mjs draft) and have the critic check it before rendering.`);
  else if (sbReview?.verdict !== 'ship' || sbReview.storyboardSha !== sha(fs.readFileSync(sb))) blocked('The storyboard has no passing critic review for its current text. Run node photoreal/critic.mjs storyboard.');

  // ---------- code shots ----------
  if (doing('code') && code.length) run('node', [path.join(HERE, 'film.mjs'), '--song', SONG, '--only', code.map((s) => s.id).join(','), ...(opt('tier') ? ['--tier', opt('tier')] : [])], `the code shots (${code.map((s) => s.id).join(' ')})`);
  // ---------- generated shots ----------
  if (doing('h3') && gen.length) run('node', [path.join(HERE, 'photorealistic.mjs'), '--song', SONG, ...(flag('no-tuck') ? ['--no-tuck'] : []), '--reuse'], `the generated shots (${gen.map((s) => s.id).join(' ')}) on H3`);

  // ---------- join ----------
  if (doing('join')) {
    const pieces = [];
    const done = new Set();
    for (const s of scenes) {
      if (s.source !== 'h3') { pieces.push({ ids: [s.id], file: codeSegment(OUT, s, tier), frames: framesOf(s) }); continue; }
      const u = units(film).find((x) => x.scenes.includes(s.id));
      if (done.has(u.id)) continue;
      done.add(u.id);
      const us = scenes.filter((x) => u.scenes.includes(x.id));
      pieces.push({ ids: u.scenes, file: path.join(OUT, 'photorealistic', `${u.id}.mp4`), frames: us.reduce((k, x) => k + framesOf(x), 0) });
    }
    const missing = pieces.filter((p) => !fs.existsSync(p.file));
    if (missing.length) blocked(`Shots not made yet: ${missing.map((p) => p.ids.join('+')).join(', ')} (${missing.map((p) => path.relative(SONG, p.file)).join(', ')}).`);
    // every piece on the same grid: 1920x1080, 24 fps, its exact frame count (last frame held if short)
    const parts = pieces.map((p, i) => {
      const f = path.join(WORK, `part-${String(i).padStart(3, '0')}.mp4`);
      ff(['-i', p.file, '-an', '-vf', `fps=${H3.fps},scale=1920:1080:force_original_aspect_ratio=increase:flags=lanczos,crop=1920:1080,tpad=stop_mode=clone:stop=${p.frames},trim=end_frame=${p.frames},setpts=PTS-STARTPTS,format=yuv420p`,
        '-c:v', 'libx264', '-preset', 'medium', '-crf', '10', f], `conforming ${p.ids.join('+')}`);
      return f;
    });
    const list = path.join(WORK, 'parts.txt');
    fs.writeFileSync(list, parts.map((f) => `file '${f.replace(/'/g, "'\\''")}'`).join('\n') + '\n');
    const picture = path.join(WORK, 'picture.mp4');
    ff(['-f', 'concat', '-safe', '0', '-i', list, '-c', 'copy', picture], 'joining the shots');
    let cut = picture;
    if (film.popcam !== false && !flag('no-popcam')) {
      if (!fs.existsSync(path.join(SONG, 'data', 'music.json'))) blocked('No data/music.json for the pop camera. Run with --stage music first.');
      cut = path.join(WORK, 'camera.mp4');
      run('python3', [path.join(HERE, 'lib', 'popcam.py'), '--song', SONG, '--video', picture, '--out', cut, '--plan', path.join(WORK, 'popcam.json')], 'the pop camera (lib/popcam.py)');
    } else notes.push('The pop camera was off for this cut.');
    const out = path.resolve(opt('out', path.join(OUT, 'film.mp4')));
    const end = scenes.at(-1).to;
    ff(['-i', cut, '-i', path.join(SONG, 'media', 'song.wav'), '-map', '0:v', '-map', '1:a', '-c:v', 'libx264', '-preset', 'slow', '-crf', tier === 'fast' ? '18' : '12', '-pix_fmt', 'yuv420p',
      '-color_primaries', 'bt709', '-color_trc', 'bt709', '-colorspace', 'bt709', '-c:a', 'aac', '-b:a', '320k', '-t', String(end), '-movflags', '+faststart', out], 'laying the song under the cut');
    // what the film was made from, for the check and critic bindings
    const content = Object.fromEntries(pieces.flatMap((p) => { const h = sha(fs.readFileSync(p.file)); return p.ids.map((id) => [id, h]); }));
    fs.writeFileSync(out.replace(/\.mp4$/, '') + '.content.json', JSON.stringify(content, null, 1) + '\n');
    const genIds = gen.map((s) => s.id);
    fs.writeFileSync(out.replace(/\.mp4$/, '') + '.label.txt', `This film contains AI-generated video: shots ${genIds.join(', ')} were generated with MiniMax H3 (steered by the Ark engine's code renders or Blender greybox guides where noted in film.json). The other shots are drawn in code. Label it as AI-generated wherever it is published.\n`);
    if (gen.length) notes.push(`Contains generated video (MiniMax H3): shots ${genIds.join(', ')}. Label it as AI-generated when it is published (out/film.label.txt).`);
    writeStatus(path.join(OUT, 'STATUS.md'), { song: SONG, state: 'done', output: out, notes: ['Next: node photoreal/check.mjs --label final, then node photoreal/critic.mjs film.', ...notes], elapsed: (Date.now() - started) / 1000 });
    console.log('wrote', out);
  }
}
